// A round that reports nothing adds nothing; the total is undefined until some round reports.
export function addRoundUsage(total: TurnUsage | undefined, round: UsageMetadata | undefined): TurnUsage | undefined {
  if (round === undefined) return total;
  return {
    inputTokens: round.inputTokens + (total?.inputTokens ?? 0),
    outputTokens: round.outputTokens + (total?.outputTokens ?? 0),
    totalTokens: round.totalTokens + (total?.totalTokens ?? 0),
  };
}

